-- Draft migration 1. Freeze exact complete bytes before first release.
CREATE TABLE migration_history (
    version INTEGER PRIMARY KEY CHECK(version > 0),
    checksum TEXT NOT NULL CHECK(length(checksum)=71),
    predecessor_version INTEGER NOT NULL,
    predecessor_checksum TEXT,
    package_identity TEXT NOT NULL
) STRICT;
CREATE TABLE ledger_meta (
    singleton INTEGER PRIMARY KEY CHECK(singleton=1),
    epoch TEXT NOT NULL,
    generation TEXT NOT NULL,
    mode TEXT NOT NULL CHECK(mode IN ('normal','reconciliation'))
) STRICT;
CREATE TABLE tasks (
    id TEXT PRIMARY KEY,
    principal_uid INTEGER NOT NULL CHECK(principal_uid BETWEEN 0 AND 4294967295),
    principal_role TEXT NOT NULL,
    spec BLOB NOT NULL CHECK(length(spec) BETWEEN 1 AND 1048576),
    criteria_digest TEXT NOT NULL,
    generation TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('admitted','queued','running','verifying','repair_pending','cancellation_requested','blocked','accepted','failed','cancelled','abandoned','effect_unknown')),
    cancellation INTEGER NOT NULL DEFAULT 0 CHECK(cancellation IN (0,1)),
    accepted_event TEXT REFERENCES events(id),
    limit_ms INTEGER NOT NULL CHECK(limit_ms BETWEEN 1 AND 1200000),
    spent_ms INTEGER NOT NULL DEFAULT 0 CHECK(spent_ms>=0),
    reserved_work_ms INTEGER NOT NULL CHECK(reserved_work_ms>=0),
    reserved_verify_ms INTEGER NOT NULL CHECK(reserved_verify_ms>=0),
    CHECK(spent_ms+reserved_work_ms+reserved_verify_ms<=limit_ms)
) STRICT;
CREATE TABLE roster_records (
    id TEXT PRIMARY KEY,
    principal_uid INTEGER NOT NULL CHECK(principal_uid BETWEEN 0 AND 4294967295),
    principal_role TEXT NOT NULL,
    revision TEXT NOT NULL,
    definition BLOB NOT NULL CHECK(length(definition) BETWEEN 1 AND 1048576),
    disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN (0,1)),
    observation_id TEXT REFERENCES roster_observations(id)
) STRICT;
CREATE TABLE operations (
    principal_uid INTEGER NOT NULL,
    principal_role TEXT NOT NULL,
    action TEXT NOT NULL,
    version INTEGER NOT NULL CHECK(version=1),
    request_key TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    resource_id TEXT REFERENCES tasks(id),
    roster_id TEXT REFERENCES roster_records(id),
    request_object TEXT REFERENCES artifacts(digest),
    request_row INTEGER CHECK(request_row BETWEEN 0 AND 255),
    result BLOB NOT NULL,
    CHECK ((resource_id IS NULL) <> (roster_id IS NULL)),
    CHECK ((action='task.submit' AND resource_id IS NOT NULL AND request_object IS NULL AND request_row IS NULL)
        OR (action IN ('roster.update','roster.disable') AND roster_id IS NOT NULL AND request_object IS NOT NULL)),
    PRIMARY KEY(principal_uid,principal_role,action,version,request_key)
) STRICT;
CREATE TABLE attempts (
    id TEXT PRIMARY KEY,
    task_id TEXT NOT NULL REFERENCES tasks(id),
    generation TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('queued','running','settled','unknown')),
    effect TEXT NOT NULL CHECK(effect IN ('none','committed','pending','unknown')),
    cleanup TEXT NOT NULL CHECK(cleanup IN ('none','pending','settled','unknown')),
    used_ms INTEGER CHECK(used_ms>=0),
    UNIQUE(task_id,generation)
) STRICT;
CREATE UNIQUE INDEX one_unsettled_attempt ON attempts(task_id) WHERE state!='settled';
CREATE TABLE events (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    id TEXT NOT NULL UNIQUE,
    task_id TEXT REFERENCES tasks(id),
    roster_id TEXT REFERENCES roster_records(id),
    generation TEXT NOT NULL,
    kind TEXT NOT NULL,
    body BLOB NOT NULL,
    CHECK ((task_id IS NULL) <> (roster_id IS NULL))
) STRICT;
CREATE TABLE artifacts (
    digest TEXT PRIMARY KEY,
    size INTEGER NOT NULL CHECK(size BETWEEN 0 AND 16777216)
) STRICT;
CREATE TABLE acceptances (
    event_id TEXT PRIMARY KEY REFERENCES events(id),
    task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id),
    attempt_id TEXT NOT NULL REFERENCES attempts(id),
    generation TEXT NOT NULL,
    criteria_digest TEXT NOT NULL,
    manifest_digest TEXT NOT NULL REFERENCES artifacts(digest)
) STRICT;
CREATE TABLE acceptance_objects (
    event_id TEXT NOT NULL REFERENCES acceptances(event_id),
    digest TEXT NOT NULL REFERENCES artifacts(digest),
    PRIMARY KEY(event_id,digest)
) STRICT;
CREATE TABLE outbox (
    event_id TEXT NOT NULL REFERENCES events(id),
    recipient TEXT NOT NULL,
    delivered INTEGER NOT NULL DEFAULT 0 CHECK(delivered IN (0,1)),
    PRIMARY KEY(event_id,recipient)
) STRICT;

CREATE TABLE roster_revisions (
    record_id TEXT NOT NULL REFERENCES roster_records(id),
    revision TEXT NOT NULL,
    definition BLOB NOT NULL,
    disabled INTEGER NOT NULL CHECK(disabled IN (0,1)),
    event_id TEXT NOT NULL UNIQUE REFERENCES events(id),
    PRIMARY KEY(record_id,revision)
) STRICT;
CREATE TABLE roster_observations (
    id TEXT PRIMARY KEY,
    record_id TEXT NOT NULL,
    revision TEXT NOT NULL,
    instance_id TEXT REFERENCES roster_instances(id),
    body BLOB NOT NULL,
    sequence INTEGER NOT NULL UNIQUE REFERENCES events(sequence),
    FOREIGN KEY(record_id,revision) REFERENCES roster_revisions(record_id,revision)
) STRICT;
CREATE TABLE roster_instances (
    id TEXT PRIMARY KEY,
    task_id TEXT NOT NULL REFERENCES tasks(id),
    attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
    agent_record_id TEXT NOT NULL,
    agent_record_version TEXT NOT NULL,
    revision TEXT NOT NULL,
    body BLOB NOT NULL,
    FOREIGN KEY(agent_record_id,agent_record_version) REFERENCES roster_revisions(record_id,revision)
) STRICT;
CREATE TABLE roster_instance_history (
    instance_id TEXT NOT NULL REFERENCES roster_instances(id),
    revision TEXT NOT NULL,
    body BLOB NOT NULL,
    event_id TEXT NOT NULL UNIQUE REFERENCES events(id),
    PRIMARY KEY(instance_id,revision)
) STRICT;
CREATE TABLE roster_pins (
    attempt_id TEXT NOT NULL REFERENCES attempts(id),
    record_id TEXT NOT NULL,
    record_version TEXT NOT NULL,
    body BLOB NOT NULL,
    PRIMARY KEY(attempt_id,record_id),
    FOREIGN KEY(record_id,record_version) REFERENCES roster_revisions(record_id,revision)
) STRICT;
CREATE TABLE roster_cancel_causes (
    event_id TEXT NOT NULL REFERENCES events(id),
    record_id TEXT NOT NULL REFERENCES roster_records(id),
    task_id TEXT NOT NULL REFERENCES tasks(id),
    attempt_id TEXT NOT NULL REFERENCES attempts(id),
    PRIMARY KEY(event_id,attempt_id)
) STRICT;

-- One independently collected verification return per attempt. Unknown returns
-- retain reservations; T07 owns later reconciliation and restart continuation.
CREATE TABLE verifications (
    attempt_id TEXT PRIMARY KEY REFERENCES attempts(id),
    event_id TEXT NOT NULL UNIQUE REFERENCES events(id),
    subject_digest TEXT NOT NULL CHECK(length(subject_digest)=71),
    evidence_digest TEXT NOT NULL REFERENCES artifacts(digest),
    verdict TEXT NOT NULL CHECK(verdict IN ('passed','failed','invalid','error','timeout','cancelled')),
    used_ms INTEGER CHECK(used_ms>=0),
    cleanup_settled INTEGER NOT NULL CHECK(cleanup_settled IN (0,1))
) STRICT;

-- Terminal nonacceptance preserves exact stop evidence and outbox identity.
CREATE TABLE task_stops (
    task_id TEXT PRIMARY KEY REFERENCES tasks(id),
    event_id TEXT NOT NULL UNIQUE REFERENCES events(id),
    evidence_digest TEXT NOT NULL REFERENCES artifacts(digest),
    reason TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('failed','cancelled'))
) STRICT;
